{
  "components": [
    {
      "type": "date",
      "quote": "29 March 2023",
      "gist": "Date of the Federal Council's decision"
    },
    {
      "type": "claim",
      "quote": "the Federal Council took a landmark decision on optimising its crisis management at a time of increasing global uncertainty",
      "gist": "Federal Council made a significant decision to improve crisis management amid global uncertainty"
    },
    {
      "type": "claim",
      "quote": "The focus is on managing emerging crises within the existing structures of the Federal Administration for as long as possible, but with accelerated procedures to increase efficiency",
      "gist": "Focus is on handling crises within current Federal Administration structures with faster procedures for efficiency"
    },
    {
      "type": "claim",
      "quote": "the early detection of crises is to be strengthened in order to be able to react to changes in the situation in a timely manner",
      "gist": "Early crisis detection will be enhanced to enable timely response to changing situations"
    },
    {
      "type": "entity",
      "quote": "the new Ordinance on the Crisis Organisation of the Federal Administration (OCOFA)",
      "gist": "New ordinance governing crisis organization in the Federal Administration"
    }
  ]
}
